//! Golden canonical bytes and bundle hash of the measurement-classification
//! protocol bundle. The expected values are literals from the old genesis
//! code. They are not computed from the constructor under test.

use alloy_primitives::hex;
use outbe_ocomp_protocol::{
    profile::{measurement_protocol_bundle_v1, poc_schema_limits, ProtocolBundleV1},
    test_utils::minimal_protocol_bundle,
    ProtocolError,
};

const MEASUREMENT_BUNDLE_HEX: &str = "";
const MEASUREMENT_BUNDLE_HASH_HEX: &str =
    "6ad7966dbfa360e9ed97c9239d2d2485886f770b3aeef8cccd655824fe6f9543";

fn assert_golden(bundle: &ProtocolBundleV1) -> Result<(), ProtocolError> {
    let limits = poc_schema_limits();
    assert_eq!(
        hex::encode(bundle.encode_canonical(&limits)?),
        MEASUREMENT_BUNDLE_HEX
    );
    assert_eq!(
        hex::encode(bundle.protocol_bundle_hash(&limits)?),
        MEASUREMENT_BUNDLE_HASH_HEX
    );
    Ok(())
}

#[test]
fn measurement_protocol_bundle_matches_genesis_golden() -> Result<(), ProtocolError> {
    assert_golden(&measurement_protocol_bundle_v1())
}

#[test]
fn minimal_test_bundle_matches_genesis_golden() -> Result<(), ProtocolError> {
    assert_golden(&minimal_protocol_bundle())
}
